settings.css:
/* Main font, size, colors */

html,
body,
#root,
.chat-room,
.chat-room__content,
.scrollable-area,
.tw-root--theme-dark {
  background: transparent !important;
  background-color: transparent !important;

  font-family: 'Atkinson Hyperlegible Next', monospace !important;
  font-size: 100px !important;
  line-height: 1.2 !important;

  color: #ffffff !important;
}

/* Username styling */

.chat-author__display-name {
  font-weight: 500 !important;
  font-size: 100px !important;
}

/* Message styling */

.text-fragment {
  color: #ffffff !important;
  font-size: 100px !important;
}

/* --------- Chat layout */

/* Remove Twitch's default separator */

.chat-line__message > span:not(.chat-author__display-name):first-child {
  display: none !important;
}

/* Emotes */

.chat-image,
img.chat-line__message--emote,
img[class*="emote"],
img.emoji {
  display: inline-block !important;

  height: 2.4em !important;
  width: auto !important;

  margin: 0 2px !important;
  padding: 0 !important;

  vertical-align: middle !important;
}

.chat-line__message {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: baseline !important;
  line-height: 1.2 !important;
}

.chat-line__message > span {
  align-items: center !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* --------- Utility */

/* Hide scrollbar */

::-webkit-scrollbar {
  display: none;
}

/* --------- Remove UI elements */

/* Stream Chat header */

.Layout-sc-1xcs6mc-0.jmERFg.stream-chat-header,
.InjectLayout-sc-1i43xsx-0.iDMNUO {
  display: none !important;
}

/* Top gifters leaderboard */

.channel-leaderboard-header-rotating__users,
.ScTransitionBase-sc-hx4quq-0.hhLPgp.tw-transition {
  display: none !important;
  height: 0 !important;
  max-height: 0 !important;
  overflow: hidden !important;
}

/* Gift popups */

.Layout-sc-1xcs6mc-0.ikqKEy {
  display: none !important;
}

/* Animated emote banner */

.Layout-sc-1xcs6mc-0.fysEov,
.Layout-sc-1xcs6mc-0.bLZXTb,
.Layout-sc-1xcs6mc-0.kklSOA.chat-input,
.ScCoreButton-sc-ocjdkq-0.evvsZQ,
.CoreText-sc-1txzju1-0.cWFBTs {
  display: none !important;
}

/* Cookies banner */

[data-a-target="consent-banner"],
.consent-banner,
div[class*="consent"] {
  display: none !important;
}

/* Predictions banner */

.Layout-sc-1xcs6mc-0.cEllaX {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  max-height: 0 !important;
  overflow: hidden !important;
}

/* User badges */

.chat-badge,
.chat-badge-container,
img.chat-badge {
  display: none !important;
}

/* FFZ reply references */

.ffz--fix-reply-line,
.chat-line__reply,
[class*="reply"] {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: 0 !important;
  line-height: 0 !important;
}

/* Cheers / gifted subs activity carousel */

.Layout-sc-1xcs6mc-0.eOHCrm {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  max-height: 0 !important;
  overflow: hidden !important;
  margin: 0 !important;
  padding: 0 !important;
}
